use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::{BTreeMap,BTreeSet},fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/affine-redc-offset176";
fn read(n:&str)->Value{serde_json::from_slice(&fs::read(format!("{R}/{n}")).unwrap()).unwrap()}fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn receipts(dir:&str)->usize{let wf=read(&format!("{dir}/result.json"));assert_eq!(wf["status"],"complete");let steps=wf["steps"].as_array().unwrap();for step in steps{let step=step.as_str().unwrap();let exit=read(&format!("{dir}/{step}/exit.json"));assert_eq!(exit["success"],true);assert_eq!(exit["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(&format!("{R}/{dir}/{step}/{stream}.log")),exit[format!("{stream}_sha256")].as_str().unwrap());}}steps.len()}
fn main(){let mut all=BTreeMap::new();for n in["model-pins.json","native-pins.json","native-fixed-pins.json","codegen-pins.json","decode-pins.json"]{for(p,h)in read(n).as_object().unwrap(){if let Some(old)=all.insert(p.clone(),h.as_str().unwrap().to_owned()){assert_eq!(old,h.as_str().unwrap());}}}for(p,h)in&all{assert_eq!(&hash(p),h,"{p}");}
 let commands=receipts("model-runs")+receipts("native-fixed-runs")+receipts("codegen-runs")+receipts("decode-runs");assert_eq!(commands,29);let fail=read("native-runs/build-deferred-offset-field/exit.json");assert_eq!(fail["success"],false);assert_eq!(fail["returncode"],1);assert!(fs::read_to_string(format!("{R}/native-runs/build-deferred-offset-field/stderr.log")).unwrap().contains("error[E0061]"));
 let model=read("model-result.json");assert_eq!(model["complete"],true);let(mut model_outputs,mut cancel_rows)=(0,0);for case in model["cases"].as_array().unwrap(){let n=case["edge_count"].as_u64().unwrap();assert_eq!(n,72);let rows=n*n+2048+512;assert_eq!(case["rows_per_operation"],rows);for op in case["operations"].as_array().unwrap(){assert_eq!(op["outputs"],rows);assert_eq!(op["CIOS_cancellation_rows"],5*rows);assert!(op["negative_carries"].as_u64().unwrap()>0);assert!(op["negative_offset_coefficients"].as_u64().unwrap()>0);assert!(op["reduce2p"].as_u64().unwrap()>0);let max=op["max_signed_offset_coefficient"].as_str().unwrap().parse::<i128>().unwrap();assert!(max<8*(1i128<<52));if op["mode"]=="mul_double_minus_sum"{assert!(op["reduce4p"].as_u64().unwrap()>0);}else{assert_eq!(op["reduce4p"],0);}model_outputs+=rows;cancel_rows+=5*rows;}}assert_eq!(model_outputs,77440);assert_eq!(cancel_rows,387200);
 let stdout=fs::read_to_string(format!("{R}/native-fixed-runs/run-native-offset-oracles/stdout.log")).unwrap();assert!(stdout.contains("2 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out"));let records=stdout.lines().filter_map(|l|l.split_once("AFFINE_OFFSET_NATIVE ").map(|(_,v)|v)).collect::<Vec<_>>();assert_eq!(records.len(),2);let mut primes=BTreeSet::new();let mut native=0u64;for record in records{let fields=record.split_whitespace().filter_map(|w|w.split_once('=')).collect::<BTreeMap<_,_>>();assert!(primes.insert(fields["prime"]));assert_eq!(fields["edges"],"72");assert_eq!(fields["rows"],"7744");for key in["raw_outputs","Ark_exports","original_exports"]{assert_eq!(fields[key],"309760");}native+=fields["raw_outputs"].parse::<u64>().unwrap();}assert_eq!(native,619520);
 let manifest_path="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json";let manifest:Value=serde_json::from_slice(&fs::read(manifest_path).unwrap()).unwrap();let suffix="\n// Private deferred affine-offset study; original methods stay byte-exact.\n#[cfg(all(zopro_affine_offset, zopro_cios_cancel_carry))]\nmod affine_offset;\n";
 for(rel,expected)in manifest["source_files_sha256"].as_object().unwrap(){let prod=format!("/home/ubuntu/src/zk-tools/zopro/{rel}");assert_eq!(hash(&prod),expected.as_str().unwrap());let fixed=format!("{R}/source-fixed/{rel}");if rel=="crates/zopro-bn254/src/ifma8.rs"{let text=fs::read_to_string(&fixed).unwrap();assert_eq!(text.strip_suffix(suffix).unwrap().as_bytes(),fs::read(&prod).unwrap());}else{assert_eq!(hash(&fixed),expected.as_str().unwrap());}}
 let parent=fs::read_to_string(format!("{R}/source/crates/zopro-bn254/src/ifma8.rs")).unwrap();let start=parent.find("    #[inline(always)]\n    fn product_cios<const FUSED: bool>").unwrap();let end=parent[start..].find("    /// Inputs must each be below p.").unwrap()+start;let old=&parent[start..end];let tail=old.rfind("            for j in 0..4 {").unwrap();let header="fn product_cios<const FUSED: bool>(&self, b: &Self, c: &Self, d: &Self) -> Self";let newheader="fn offset_product<const FUSED: bool, const DOUBLE: bool, const SUM: bool>(&self, b: &Self, c: &Self, d: &Self, x: &Self, y: &Self) -> Self";
 let expected=fs::read_to_string(format!("{R}/field-prelude.rs")).unwrap()+"\n"+&old[..tail].replace(header,newheader).replace("if MIXED {","if true {")+&fs::read_to_string(format!("{R}/field-tail.rs")).unwrap()+"        }\n    }\n\n"+&fs::read_to_string(format!("{R}/field-suffix.rs")).unwrap();let actual=fs::read_to_string(format!("{R}/source-fixed/crates/zopro-bn254/src/ifma8/affine_offset.rs")).unwrap();assert_eq!(actual,expected.replace("Self(Self::offset_reduce_raw(result, twice))","Self(Self::offset_reduce_raw(result, twice), PhantomData)"));
 let repair=read("native-repair.json");let rows=repair["sources"].as_array().unwrap();assert_eq!(rows.len(),177);assert_eq!(rows.iter().filter(|r|r["changed"]==true).count(),1);for row in rows{let rel=row["relative"].as_str().unwrap();assert_eq!(hash(&format!("{R}/source/{rel}")),row["initial"].as_str().unwrap());assert_eq!(hash(&format!("{R}/source-fixed/{rel}")),row["fixed"].as_str().unwrap());}
 let targets=read("decode-targets.json");assert_eq!(targets.as_array().unwrap().len(),20);let mut code=vec![];for target in targets.as_array().unwrap(){let name=target["symbol"].as_str().unwrap();let step=target["step"].as_str().unwrap();let text=fs::read_to_string(format!("{R}/decode-runs/{step}/stdout.log")).unwrap();let address=target["address"].as_u64().unwrap();let bytes=target["bytes"].as_u64().unwrap();let(mut sites,mut ifma,mut calls,mut stack,mut zmm_stack,mut shifts)=(0,0,0,0,0,0);for line in text.lines(){let Some((left,right))=line.trim().split_once(':')else{continue};let Ok(ip)=u64::from_str_radix(left,16)else{continue};assert!(address<=ip&&ip<address+bytes);let op=right.trim();if op.is_empty(){continue;}let mnemonic=op.split_whitespace().next().unwrap();sites+=1;ifma+=u64::from(mnemonic.starts_with("vpmadd52"));calls+=u64::from(mnemonic.starts_with("call"));let is_stack=op.contains("(%rsp")||op.contains("(%rbp");stack+=u64::from(is_stack);zmm_stack+=u64::from(is_stack&&op.contains("%zmm"));shifts+=u64::from(mnemonic.starts_with("vpsra")||mnemonic.starts_with("vpsrl"));}let mode=name.rsplit('_').next().unwrap().parse::<usize>().unwrap();assert_eq!(ifma,if mode>=3{150}else{100});assert_eq!(calls,0);assert!(sites>100);code.push(json!({"symbol":name,"bytes":bytes,"instruction_sites":sites,"IFMA_sites":ifma,"call_sites":calls,"RSP_RBP_memory_operand_sites":stack,"ZMM_stack_operand_sites":zmm_stack,"packed_shift_sites":shifts,"source_sha256":hash(&format!("{R}/decode-runs/{step}/stdout.log"))}));}
 let mut comparisons=vec![];for prime in["fq","fr"]{for mode in 0..5{let get=|arm:&str|code.iter().find(|v|v["symbol"]==format!("cg_{arm}_{prime}_{mode}")).unwrap();let old=get("old");let new=get("new");comparisons.push(json!({"prime":prime,"mode":mode,"old":old,"new":new,"instruction_site_delta":new["instruction_sites"].as_i64().unwrap()-old["instruction_sites"].as_i64().unwrap(),"bytes_delta":new["bytes"].as_i64().unwrap()-old["bytes"].as_i64().unwrap(),"not_dynamic_work_or_speed":true}));}}
 let identities=BTreeMap::from_iter(["libzopro_bn254-fixed.rlib","libzopro_bn254-generic-fixed.rlib","native-fixed-tests","codegen-consumer"].map(|n|(n,hash(&format!("{R}/{n}")))));
 let qualification=json!({"passed":true,"pins":all.len(),"successful_workflow_commands":commands,"initial_native_compile_failure_retained":true,"arithmetic_unchanged_by_tuple_marker_fix":true,"model_outputs":model_outputs,"model_cancellation_steps":cancel_rows,"native_lane_outputs":native,"Ark_canonical_exports":native,"original_canonical_exports":native,"native_tests":2,"R256_primes":["Fq","Fr"],"generic_field_compile_passed":true,"all176_production_sources_unchanged":true,"private_source_files":177,"CIOS_prefix_byte_identity_reconstructed":true,"matched_consumers_decoded_once":20,"codegen_comparisons":comparisons,"compiled_artifact_identities":identities,"complete_point_caller_qualified":false,"speed_measured":false,"native_caller_stage_selected":true,"SDK_requests":0,"Gnark_exports":0,"canonical_proofs":36477,"production_changed":false,"adopted":false,"goal_complete":false,"limits":["Field/radix qualification only; no complete point/prefix/tail/exception/core/SDK performance result","Static instruction/stack-operand sites are not dynamic retirement, spills, stack peaks, CPU cycles or RAM minima","Separate reader audits source/artifact/count/codegen evidence; BigInt and Arkworks checks execute inside the model/native tests, not again in this reader"]});let out=format!("{R}/qualification.json");assert!(!Path::new(&out).exists());fs::write(out,serde_json::to_vec_pretty(&qualification).unwrap()).unwrap();println!("Source/artifact/count/codegen qualification PASS: {model_outputs} math outputs, {native} native lane outputs,20 new decodes");for row in qualification["codegen_comparisons"].as_array().unwrap(){println!("{} mode{} sites {}->{} bytes {}->{}",row["prime"],row["mode"],row["old"]["instruction_sites"],row["new"]["instruction_sites"],row["old"]["bytes"],row["new"]["bytes"]);}}
